  ['REAR SUBFRAME'] = 'SUBCHASIS TRASERO',
  ['The vehicle has no subframe or suspension on that side: put its own subframe back (Parts menu) and try again.'] = 'El vehículo no tiene subchasis ni suspensión en ese lado: vuelve a poner su propio subchasis (menú Parts) e inténtalo de nuevo.',
  ['The whole donor subframe with everything on it (suspension, hubs, wheels) in place of your subframe. The donor engine (of a mid-engined car) stays out - your own engine drives the new wheels through the universal drivetrain. A suspension from another vehicle can still be swapped into it afterwards.'] = 'Todo el subchasis del donante con todo lo que lleva (suspensión, bujes, ruedas) en lugar de tu subchasis. El motor del donante (de un coche de motor central) se queda fuera - tu propio motor mueve las ruedas nuevas con la transmisión universal. Después aún se le puede poner la suspensión de otro vehículo.',
  ['The donor subframe\'s engine stays out - your own engine drives the new wheels through the universal drivetrain (%s).'] = 'El motor del subchasis del donante se queda fuera - tu propio motor mueve las ruedas nuevas con la transmisión universal (%s).',
  ['Comes with (%d of %d)'] = 'Viene con (%d de %d)',
  ['Untick what you don\'t need: that part and everything below it stays out of the preview and the vehicle.'] = 'Desmarca lo que no necesites: esa pieza y todo lo que cuelga de ella no aparece ni en la vista previa ni en el vehículo.',
  ['None'] = 'Ninguna',
  ['Only the part itself, without its sub parts (e.g. a frame without its body, engine and suspension).'] = 'Solo la pieza, sin sus subpiezas (p. ej. un chasis sin carrocería, motor ni suspensión).',
  ['(engine - no logic)'] = '(motor - sin lógica)',
  ['A ticked donor engine comes as a part only (model and weight, it does not run) - your own engine still drives the vehicle.'] = 'Un motor del donante marcado viene solo como pieza (modelo y peso, no funciona) - tu propio motor sigue moviendo el vehículo.',
  ['Update the preview'] = 'Actualizar la vista previa',
  ['No picture yet - tick "Take part pictures" below the list.'] = 'Aún no hay imagen - marca "Hacer fotos de las piezas" debajo de la lista.',
  ['Cut this part (cuts: %d)'] = 'Cortar esta pieza (cortes: %d)',
  ['Cut part of the preview off (e.g. keep only the front of a frame), then move it and ATTACH - only what is left comes onto the vehicle.'] = 'Corta parte de la vista previa (p. ej. deja solo el frente de un chasis), luego muévela y FÍJALA - solo lo que queda va al vehículo.',
  ['Could not read the part.'] = 'No se pudo leer la pieza.',
  ['Part length: %.2f m'] = 'Largo de la pieza: %.2f m',
  ['CUT THE PART'] = 'CORTAR LA PIEZA',
  ['The part is cut - move it and ATTACH.'] = 'La pieza está cortada - muévela y FÍJALA.',
  ['Whole part again'] = 'La pieza entera otra vez',
  ['There is nothing of the part to cut there.'] = 'En ese sitio no hay nada de la pieza que cortar.',
  ['Steering lock (front wheel angle)'] = 'Giro de la dirección (ángulo de las ruedas delanteras)',
  ['Change the steering lock'] = 'Cambiar el giro de la dirección',
  ['Virtual steering: each front hub gets a kingpin of its own and the steering turns it exactly up to this angle; the vehicle\'s own steering cylinders only hold the wheels straight.'] = 'Dirección virtual: cada buje delantero recibe su propio pivote (kingpin) y la dirección lo gira exactamente hasta este ángulo; los cilindros de dirección del vehículo solo mantienen las ruedas rectas.',
  ['(the vehicle\'s own: ~%.0f deg)'] = '(el propio del vehículo: ~%.0f deg)',
  ['Wheel angle'] = 'Ángulo de las ruedas',
  ['Up to 80 degrees (further, the tie rod would flip over). Above ~45 the wheels may rub the body or the arms; if the vehicle gets unstable, the change is undone by itself.'] = 'Hasta 80 grados (más allá la barra de dirección se daría la vuelta). Por encima de ~45 las ruedas pueden rozar la carrocería o los brazos; si el vehículo se vuelve inestable, el cambio se deshace solo.',
  ['APPLY THE STEERING'] = 'APLICAR LA DIRECCIÓN',
  ['The front wheels will turn up to ~%d deg.'] = 'Las ruedas delanteras girarán hasta ~%d deg.',
  ['The steering lock is factory again.'] = 'El giro de la dirección vuelve a ser el de fábrica.',
  ['The vehicle\'s steering cylinders hold the wheels straight, the virtual steering turns them.'] = 'Los cilindros de dirección del vehículo mantienen las ruedas rectas, la dirección virtual las gira.',
  ['The front wheel hubs could not be separated - the vehicle keeps its own steering.'] = 'No se pudieron separar los bujes delanteros - el vehículo conserva su propia dirección.',
  ['State: on - front wheels up to ~%d deg.'] = 'Estado: activado - ruedas delanteras hasta ~%d deg.',
  ['Only what is inside the orange shape is cut out - the rest of the part stays.'] = 'Solo se recorta lo que queda dentro de la forma naranja - el resto de la pieza se queda.',
  ['Part: length %.2f m, width %.2f m, height %.2f m'] = 'Pieza: largo %.2f m, ancho %.2f m, alto %.2f m',
}
